-- ===== id_card_template (2 rows) =====
-- Template backgrounds are PNG files; the source project recorded them with a
-- .jpg suffix. The app passes this column straight to createSignedUrl(), so
-- the value has to match the object's real name in the bucket.
-- The inserts above are ON CONFLICT DO NOTHING, so they leave an existing row
-- untouched. This corrects a database already seeded with the .jpg values.
UPDATE public.id_card_template
   SET background_image_url = replace(background_image_url, '.jpg', '.png')
 WHERE template_type IN ('card_front', 'card_back')
   AND background_image_url LIKE '%.jpg';

-- ===== id_card_template_field (20 rows, synced from live 2026-08-21) =====
-- ===== Harari / Oromiffa woreda-name placeholders, added by
-- 00000000000005_woreda_name_har_om.sql -- every woreda-name language
-- variant now has a placeholder on both card sides. =====

-- ===== woreda_name_short / woreda_name_short_en (woreda_settings), added
-- live 2026-09-01: placed via the admin template editor as new "Woreda
-- Short Name (AM)" / "(EN)" placeholder entities on card_back, between the
-- Phone No. row and the stamp/signature/QR row. Same settings-only-override
-- pattern as woreda_name_har/om -- no raw registry column to fall back to.
-- ===== stamp (woreda_settings.stamp_url, "Woreda Seal"), added live
-- 2026-09-01: PrintableCard fetched stamp_url via settingsQuery but had no
-- field_key branch to render it and no template_field row positioning it,
-- so the seal never appeared on printed cards despite being uploaded. =====

-- ===== id_card_template_field_draft, added by
-- 00000000000010_id_card_template_draft.sql -- mirrors id_card_template_field
-- row-for-row (same template_field_id UUIDs, separate PK space, no FK
-- between the tables) so a fresh deploy's template editor opens onto the
-- same state as what's published, rather than an empty canvas. =====

-- Every draft INSERT above fires trg_mark_template_draft_dirty, which flips
-- id_card_template.is_published back to false for that side. On a fresh
-- deploy that leaves both rows falsely "Draft" even though the seed inserted
-- them as published above (line ~1182) -- the two sides are, by
-- construction, in lockstep with the draft on a fresh seed, so reassert the
-- published state the earlier INSERTs already declared.
UPDATE public.id_card_template SET is_published = true WHERE template_type IN ('card_front', 'card_back');

-- width 950 (not the original 420): at 420 the Code 128 barcode prints at
-- ~150um per module on an 85.6mm card, below the 250um scanning floor. 950
-- gives ~337um, matching what CredentialBarcode's density guard requires.
-- Placeholder for the "Phone No." label already printed on the card_back
-- background artwork, which previously had no bound field under it.
-- field_key is id_number (not serial_number): the printed label here reads
-- "ID Number" and sits directly above the Code 128 barcode, which encodes
-- credential_number (13 digits, with check digit) -- serial_number is the
-- bare 12-digit body and would print one digit short of what the barcode
-- actually holds.
